import { describe, expect, it } from "vitest";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { conversationDetail } from "../src/lib/client/real-api";
import {
  contextForMessage,
  contextNote,
  readRanges,
} from "../src/lib/attachment-context";
import { FileContext } from "../src/components/AttachedFiles";
// Generated by the backend from its canonical models (contracts/examples.json).
import examples from "../../contracts/examples.json";

type Detail = Parameters<typeof conversationDetail>[0];
type Item = NonNullable<Detail["attachment_context"]>[number];
const example = examples.operations.get_conversation.response as Detail;
const m1 = example.messages[0]!;
const run1 = example.runs[0]!;

const HOSTILE = '<img src=x onerror="alert(1)">notes.txt';
const item = (over: Partial<Item> = {}): Item => ({
  run_id: run1.id,
  message_id: m1.id,
  ref: "attachment-1",
  sha256: "a".repeat(64),
  filename: HOSTILE,
  body_omitted: true,
  omission_reason: "size_limit",
  chunks: [],
  ...over,
});
const chunk = (offset: number, next_offset: number) => ({
  phase: "selection" as const,
  offset,
  next_offset,
  chunk_sha256: "c".repeat(64),
});
const render = (d: ReturnType<typeof conversationDetail>, id: string) =>
  renderToStaticMarkup(
    createElement(FileContext, { items: contextForMessage(d, id) }),
  );

describe("file context from the canonical conversation DTO (A05)", () => {
  it("absent or empty attachment_context maps to no claim at all", () => {
    const bare = { ...example, attachment_context: undefined };
    expect(conversationDetail(bare).attachment_context).toEqual([]);
    const d = conversationDetail({ ...example, attachment_context: [] });
    expect(d.attachment_context).toEqual([]);
    expect(render(d, m1.id)).toBe("");
  });

  it("maps every canonical field and keeps chunks as exact ranges", () => {
    const d = conversationDetail({
      ...example,
      attachment_context: [item({ chunks: [chunk(0, 8192)] })],
    });
    expect(d.attachment_context).toEqual([
      {
        run_id: run1.id,
        message_id: m1.id,
        ref: "attachment-1",
        sha256: "a".repeat(64),
        filename: HOSTILE,
        body_omitted: true,
        omission_reason: "size_limit",
        ranges: [
          { offset: 0, next_offset: 8192, chunk_sha256: "c".repeat(64) },
        ],
      },
    ]);
  });

  it("an omitted file with nothing read back says so, escaped", () => {
    const d = conversationDetail({
      ...example,
      attachment_context: [item()],
    });
    const html = render(d, m1.id);
    expect(html).toContain(
      "Original kept as sent; omitted from bounded attachment context.",
    );
    expect(html).toContain("larger than the bounded context&#x27;s size limit");
    expect(html).not.toContain("Read back");
    expect(html).toContain("&lt;img");
    expect(html).not.toContain("<img");
  });

  it("read-back ranges are stated exactly and never as the whole file", () => {
    const d = conversationDetail({
      ...example,
      attachment_context: [
        item({
          // Out of order, overlapping, plus an empty read at EOF.
          chunks: [chunk(8192, 16384), chunk(0, 8192), chunk(4096, 6000)],
        }),
        item({ ref: "attachment-2", chunks: [chunk(40000, 40000)] }),
      ],
    });
    const html = render(d, m1.id);
    expect(html).toContain("Read back 16,384 bytes of the original");
    expect(html).toContain("(bytes 0–16,384, end exclusive)");
    expect(html).toContain(
      "Only these ranges are confirmed by range receipts.",
    );
    for (const claim of [
      "whole file",
      "recovered",
      "full text",
      "entire",
      "weren&#x27;t read",
      "not read",
    ])
      expect(html).not.toContain(claim);
    // The omission still stands after the read-back.
    expect(html).toContain("omitted from bounded attachment context");
    // An empty EOF read is not a range that was read.
    expect(readRanges([chunk(40000, 40000)])).toEqual([]);
    expect(html.match(/<li/g)).toHaveLength(2);
  });

  it("a file given in full says nothing", () => {
    const d = conversationDetail({
      ...example,
      attachment_context: [
        item({ body_omitted: false, omission_reason: null }),
      ],
    });
    expect(contextNote(d.attachment_context![0]!)).toBeNull();
    expect(render(d, m1.id)).toBe("");
  });

  it("a follow-up with no re-attached file shows the context under itself", () => {
    const m2 = {
      ...m1,
      id: "m-follow",
      sequence: m1.sequence + 1,
      run_id: "run-2",
      attachments: [],
    };
    const d = conversationDetail({
      ...example,
      messages: [m1, m2],
      runs: [run1, { ...run1, id: "run-2" }],
      attachment_context: [item({ run_id: "run-2", chunks: [chunk(0, 100)] })],
    });
    expect(render(d, "m-follow")).toContain("Read back 100 bytes");
    expect(render(d, m1.id)).toBe("");
    // Without that run's request in view, it stays with the file's message.
    const orphan = conversationDetail({
      ...example,
      attachment_context: [item({ run_id: "run-unknown" })],
    });
    expect(render(orphan, m1.id)).toContain(
      "omitted from bounded attachment context",
    );
  });
});
